def iade_al(self, kitap_id, tarih):
    """Kitabın iadesini alır, cezayı hesaplar ve ödünç kaydını döndürür. Kitap ödünçte değilse ValueError."""
    kayit = self._aktif(kitap_id)
    if kayit is None:
        raise ValueError("kitap ödünçte değil")

    kayit.iade = tarih

    # Ceza Hesaplama
    fark = (tarih - kayit.alinma).days
    gecikme_gunu = max(0, fark - 14)

    if gecikme_gunu > 0:
        # İlk 7 gün: 2.50 TL, sonraki günler: 5.00 TL
        if gecikme_gunu <= 7:
            ceza_tutar = gecikme_gunu * 2.50
        else:
            ceza_tutar = (7 * 2.50) + (gecikme_gunu - 7) * 5.00

        # Maksimum ceza 150 TL
        ceza_tutar = min(ceza_tutar, 150.0)

        # Üye türüne göre indirim
        uye = self.uyeler[kayit.uye_id]
        if uye.tur == "ogrenci":
            ceza_tutar *= 0.5

        kayit.ceza = round(ceza_tutar, 2)
    else:
        kayit.ceza = 0.0

    return kayit

def toplam_ceza(self, uye_id: int) -> float:
    """Üyenin iade edilmiş tüm ödünçlerinin cezaları toplamı."""
    toplam = sum(k.ceza for k in self.kayitlar if k.uye_id == uye_id and k.iade is not None)
    return round(toplam, 2)

